/// No wallet yet. With a single coin (mainnet PIVX only) this is the
/// "Create new wallet / Restore wallet" screen itself; with testnets shown,
/// an "Add wallet" button that leads to the coin choice.
class EmptyWallets extends ConsumerWidget {
  const EmptyWallets({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    debugPrint("BUILD: $runtimeType");

    final isDesktop = Util.isDesktop;

    ref.watch(
      prefsChangeNotifierProvider.select((value) => value.showTestNetCoins),
    );
    final coins = shownCoins(ref);
    if (coins.length == 1) {
      return CreateOrRestoreWalletContent(
        coin: coins.first,
        padding: const EdgeInsets.only(bottom: 16),
      );
    }

    // Sized by the width, but at most 35% of the height: in landscape the
    // button below would be out of sight.
    final screen = MediaQuery.sizeOf(context);
    final side = isDesktop
        ? 280.0
        : min(screen.width / 2, screen.height * 0.35);
    return SafeArea(
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 43),
        child: ConstrainedBox(
          constraints: BoxConstraints(
            maxWidth: isDesktop ? 330 : double.infinity,
          ),
          child: Column(
            children: [
              const Spacer(flex: 2),
              Image.asset(
                Assets.persona.addWallet,
                width: side,
                height: side,
                fit: BoxFit.contain,
              ),
              SizedBox(height: isDesktop ? 30 : 16),
              Text(
                AppConfig.emptyWalletsMessage,
                textAlign: TextAlign.center,
                style: isDesktop
                    ? STextStyles.desktopSubtitleH2(context).copyWith(
                        color: Theme.of(context)
                            .extension<StackColors>()!
                            .textSubtitle1,
                      )
                    : STextStyles.subtitle(context).copyWith(
                        color: Theme.of(context)
                            .extension<StackColors>()!
                            .textSubtitle1,
                      ),
              ),
              SizedBox(height: isDesktop ? 30 : 16),
              if (isDesktop)
                const SizedBox(
                  width: 328,
                  height: 70,
                  child: AddWalletButton(isDesktop: true),
                ),
              if (!isDesktop)
                const Row(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [AddWalletButton(isDesktop: false)],
                ),
              const Spacer(flex: 5),
            ],
          ),
        ),
      ),
    );
  }
}

class AddWalletButton extends ConsumerWidget {
  const AddWalletButton({super.key, required this.isDesktop});

  final bool isDesktop;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final bool isOLED = ref.watch(themeProvider).themeId == "oled_black";

    return TextButton(
      style: Theme.of(context)
          .extension<StackColors>()!
          .getPrimaryEnabledButtonStyle(context),
      onPressed: () => pushAddWallet(context, ref, rootNavigator: isDesktop),
      child: Center(
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 16),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              isOLED
                  ? SvgPicture.asset(
                      Assets.svg.plus,
                      color: Theme.of(context)
                          .extension<StackColors>()!
                          .buttonTextPrimary,
                      width: isDesktop ? 18 : null,
                      height: isDesktop ? 18 : null,
                    )
                  : SvgPicture.asset(
                      Assets.svg.plus,
                      width: isDesktop ? 18 : null,
                      height: isDesktop ? 18 : null,
                    ),
              SizedBox(width: isDesktop ? 8 : 5),
              Text(
                l10n.walletsAddWallet,
                style: isDesktop
                    ? STextStyles.desktopButtonEnabled(context)
                    : STextStyles.button(context),
              ),
            ],
          ),
        ),
      ),
    );
  }
}
